class TimingListener : EventListener() {
    var callStart: Long = 0

    override fun callStart(call: Call) {
        callStart = System.nanoTime()
    }

    override fun dnsStart(call: Call, domainName: String) {
        println("dns begin $domainName")
    }

    override fun connectStart(call: Call, inetSocketAddress: InetSocketAddress, proxy: Proxy) {
        println("connect begin ${inetSocketAddress.hostString}")
    }

    override fun secureConnectEnd(call: Call, handshake: Handshake?) {
        println("tls done ${handshake?.cipherSuite}")
    }

    override fun callEnd(call: Call) {
        val totalMs = (System.nanoTime() - callStart) / 1_000_000
        println("call took ${totalMs}ms url=${call.request().url}")
    }
}

val client = OkHttpClient.Builder().eventListenerFactory { TimingListener() }.build()

