    val status: Int,
)

// The worker that drains the queue
class OutboxWorker(ctx, params) : CoroutineWorker(ctx, params) {
    override suspend fun doWork(): Result {
        val pending = db.outboxDao().pending()
        for (entry in pending) {
            val accepted = api.send(
                entry.operation,
                entry.payload,
                idempotencyKey = entry.clientMutationId,
            )
            when {
                accepted -> db.outboxDao().markDone(entry.id)
                isRetryable(entry) -> db.outboxDao().bumpRetry(entry.id)
                else -> db.outboxDao().markFailed(entry.id)   // visible conflict state
            }
        }
        return Result.success()
    }
}

