enum class StorageKind { DataStore, Room, Files }

fun storageFor(requirements: StorageRequirements): StorageKind = when {
    requirements.queryable -> StorageKind.Room
    requirements.sizeKb > 1024 -> StorageKind.Files
    else -> StorageKind.DataStore
}

// darkMode: Boolean            -> DataStore (one flat flag)
