// downloadedVideo: ByteArray   -> Files     (large, no queries)

suspend fun download(client: OkHttpClient, url: String, dest: File, offset: Long) {
    val request = Request.Builder()
        .url(url)
        .header("Range", "bytes=$offset-")
        .build()

    client.newCall(request).execute().use { response ->
        if (response.code != 206 && response.code != 200) return   // no partial content support
        val total = offset + (response.header("Content-Length")?.toLong() ?: 0L)
        dest.outputStream().use { out ->
            val source = response.body!!.source()
            val buffer = Buffer()
            while (true) {
                val read = source.read(buffer, 8192L)
                if (read == -1L) break
                buffer.copyTo(out)                    // progress = out.count + offset
            }
        }
    }
}

// Persist `offset` on every chunk so a cancelled run resumes, not restarts.

@Dao
interface OrderDao {
    @Transaction
    suspend fun insertOrderWithItems(order: Order, items: List<OrderItem>) {
        insert(order)
        items.forEach { insertItem(it) }   // all-or-nothing on one connection
    }

    @Transaction
    @Query("SELECT * FROM orders WHERE id = :id")
    suspend fun orderWithItems(id: Long): OrderWithItems   // consistent snapshot

    suspend fun replaceAll(orders: List<Order>) {
        db.withTransaction {
            clearAll()
            insertAll(orders)              // readers never see the empty state
        }
    }
}

interface OrderApi {
    @GET("orders/{id}")                    // safe, cacheable, retry-safe
    suspend fun getOrder(@Path("id") id: String): Order

    @POST("orders")                        // neither safe nor idempotent
    suspend fun createOrder(@Body order: NewOrder): Order

    @PUT("orders/{id}")                    // idempotent: full replace
    suspend fun replaceOrder(@Path("id") id: String, @Body order: Order): Order

    @PATCH("orders/{id}")                  // idempotent only if the patch is
    suspend fun patchOrder(@Path("id") id: String, @Body patch: OrderPatch): Order
}

